      extraWords: <EnglishAdvancedWord>[EnglishAdvancedWord("election result", "نتيجة الانتخابات"), EnglishAdvancedWord("eligible voter", "ناخب مؤهل"), EnglishAdvancedWord("ballot paper", "ورقة اقتراع"), EnglishAdvancedWord("campaign promise", "وعد انتخابي"), EnglishAdvancedWord("school representative", "ممثل المدرسة"), EnglishAdvancedWord("fair election", "انتخابات نزيهة"), EnglishAdvancedWord("opposing candidate", "مرشح منافس"), EnglishAdvancedWord("voting booth", "كابينة اقتراع"), EnglishAdvancedWord("winning margin", "فارق الفوز"), EnglishAdvancedWord("campaign team", "فريق الحملة"), EnglishAdvancedWord("student voice", "صوت الطلاب"), EnglishAdvancedWord("school assembly", "تجمع مدرسي"), EnglishAdvancedWord("election rules", "قواعد الانتخاب"), EnglishAdvancedWord("policy promise", "وعد بسياسة"), EnglishAdvancedWord("public speaking", "خطابة"), EnglishAdvancedWord("accept defeat", "يتقبل الهزيمة"), EnglishAdvancedWord("school leadership", "قيادة مدرسية"), EnglishAdvancedWord("respectful debate", "نقاش باحترام")],
      grammarTitle: "First conditional and unless",
      grammarArabic: "نستخدم if مع المضارع البسيط وwill مع الفعل الأساسي لنتيجة مستقبلية محتملة. unless تعني if not.",
      grammarExamples: <String>["If staff agree, we will open later.", "Unless we find supervision, the room will close.", "Students will vote if they register."],
