      extraWords: <EnglishAdvancedWord>[EnglishAdvancedWord("parcel tracking", "تتبع الطرود"), EnglishAdvancedWord("delivery dispute", "نزاع توصيل"), EnglishAdvancedWord("customer support", "دعم العملاء"), EnglishAdvancedWord("complaint record", "سجل الشكوى"), EnglishAdvancedWord("escalate a case", "يصعّد حالة"), EnglishAdvancedWord("response time", "وقت الاستجابة"), EnglishAdvancedWord("delivery proof", "دليل التسليم"), EnglishAdvancedWord("service delay", "تأخر الخدمة"), EnglishAdvancedWord("contact channel", "قناة تواصل"), EnglishAdvancedWord("resolution email", "رسالة حل المشكلة"), EnglishAdvancedWord("courier service", "خدمة شحن"), EnglishAdvancedWord("sorting office", "مكتب فرز"), EnglishAdvancedWord("incorrect address", "عنوان غير صحيح"), EnglishAdvancedWord("replacement item", "قطعة بديلة"), EnglishAdvancedWord("support hours", "ساعات الدعم"), EnglishAdvancedWord("satisfaction survey", "استطلاع رضا"), EnglishAdvancedWord("resolved issue", "مشكلة محلولة"), EnglishAdvancedWord("reference code", "رمز مرجعي")],
      grammarTitle: "Polite indirect questions",
      grammarArabic: "بعد Could you tell me نستخدم ترتيب الجملة الخبرية داخل السؤال: where the office is. لا نستخدم قلب الفاعل والفعل أو do داخل الجملة التابعة.",
      grammarExamples: <String>["Could you tell me where my parcel is?", "Do you know when it will arrive?", "Could you explain why the address changed?"],
      listening: "Hello Dina, I am calling about support case four hundred and sixteen. We have confirmed that your parcel was delivered to the wrong building. A replacement is scheduled for Thursday between ten and two. You will receive a tracking link on Wednesday evening. If that time is unsuitable, please reply before noon tomorrow. You do not need to contact the other building yourself; our delivery team will deal with the original parcel separately.",
